"""DES: the public standard (FIPS PUB 46, 1977) — runnable demo.
Database: The Restricted Technology Archive Database. Run: python3 demo.py (standard library only)."""
RECORD_ID = "JAH-RTA-000001"
DATA = {
  "Published": "FIPS PUB 46 (1977)",
  "Key": "56 bits",
  "Status": "Public standard; now retired"
}

def lookup(key):
    """Return the detail for a given fact."""
    return DATA.get(str(key), "No entry for %%s" %% key)

def all_keys():
    return sorted(DATA.keys())

def search(text):
    t = text.lower()
    return {k: v for k, v in DATA.items() if t in str(v).lower()}

if __name__ == "__main__":
    print("=" * 64)
    print(RECORD_ID)
    print("=" * 64)
    print("entries:", len(DATA))
    keys = all_keys()
    if keys:
        print("first:", keys[0], "->", lookup(keys[0]))
        print("last: ", keys[-1], "->", lookup(keys[-1]))

