  "Declassified": "Histories public",
  "Twist": "Revealed by mole from the start"
}

def lookup(key):
    """Return the detail for a given fact."""
    return DATA.get(str(key), "No entry for %%s" %% key)

def all_keys():
    return sorted(DATA.keys())

def search(text):
    t = text.lower()
    return {k: v for k, v in DATA.items() if t in str(v).lower()}

if __name__ == "__main__":
    print("=" * 64)
    print(RECORD_ID)
    print("=" * 64)
    print("entries:", len(DATA))
    keys = all_keys()
    if keys:
        print("first:", keys[0], "->", lookup(keys[0]))
        print("last: ", keys[-1], "->", lookup(keys[-1]))

